INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷111·太祖本纪二·广顺元年四月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/148dffeabd6a27b31ce24bf25fa5203d0cd91ab7/content/books/zizhi-tongjian/vol-290/year-0951/part-06/sources/library/jiuwudaishi-111-april-grain/source.txt", "note": "《旧五代史》卷111·太祖本纪二·广顺元年四月，段落 jiu-wudaishi-205deb4a7860-p002659；已核上下文及传主，纸本及异文待核。", "id": "a36945e7-f3bb-5935-afb5-25999156db6b"}, {"title": "旧五代史·卷111·太祖本纪二·广顺元年五月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/148dffeabd6a27b31ce24bf25fa5203d0cd91ab7/content/books/zizhi-tongjian/vol-290/year-0951/part-06/sources/library/jiuwudaishi-111-may-envoys/source.txt", "note": "《旧五代史》卷111·太祖本纪二·广顺元年五月，段落 jiu-wudaishi-205deb4a7860-p002660；已核上下文及传主，纸本及异文待核。", "id": "8eebc824-e411-56d9-88bb-cb01a96bc9dd"}, {"title": "宋史·卷479·世家二·西蜀孟氏·伊审徵", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/148dffeabd6a27b31ce24bf25fa5203d0cd91ab7/content/books/zizhi-tongjian/vol-290/year-0951/part-06/sources/library/songshi-479-yi-shenzheng/source.txt", "note": "《宋史》卷479·世家二·西蜀孟氏·伊审徵，段落 songshi-9c6e46fee832-p074972；已核上下文及传主，纸本及异文待核。", "id": "54891f3a-c2ac-530d-80d8-7f362d5ceeb0"}, {"title": "新五代史·卷70·东汉世家·郑珙出使与去世", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/148dffeabd6a27b31ce24bf25fa5203d0cd91ab7/content/books/zizhi-tongjian/vol-290/year-0951/part-06/sources/library/xinwudaishi-070-zheng-gong/source.txt", "note": "《新五代史》卷70·东汉世家·郑珙出使与去世，段落 xin-wudaishi-b08f244b9241-p003447；已核上下文及传主，纸本及异文待核。", "id": "46016120-f807-5489-965c-38a5e1abf468"}, {"title": "资治通鉴·卷290·广顺元年·三月徐州战果与沿淮政策", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4ae3eabc78dcb3f9ddd203076e0412b51fdf8d20/content/books/zizhi-tongjian/vol-290/year-0951/part-05/sources/library/tongjian-290-951-march-policies/source.txt", "note": "《资治通鉴》卷290·广顺元年·三月徐州战果与沿淮政策，段落 zizhi-tongjian-a63549944a71-p003445；已核上下文及传主，纸本及异文待核。", "id": "5183e5d6-9ce7-5392-aeb1-3712e9138aec"}, {"title": "新五代史·卷六十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/xinwudaishi-067-qian-zong-succession/source.txt", "note": "《新五代史》卷六十七，段落 xin-wudaishi-b08f244b9241-p003375；EPUB电子本，纸本及异文待核", "id": "6bc7a35e-fa90-5b15-8ce4-7a044f9b0446"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "高延昭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀官员。948年任普丰库使，孟昶原想任命他与王昭远为枢密使，因二人资历和地位较低，改任通奏使、知枢密院事。生卒年未载。", "biography": null, "status": "draft", "id": "23555921-c9e7-5941-a4d0-9976d43ac9a2"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "伊审征", "aliases": ["伊審徵", "伊审徵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀官员，太原人，《宋史》称伊审徵、字申图，记为并州人。951年由前云安榷盐使任通奏使、知枢密院事。关于母亲及其父婚配，两书叙述不同，具体对应仍待校核。生卒年尚未录入。", "biography": null, "status": "draft", "id": "a1611515-927b-50be-b3e4-084a6ff72a62"}, {"name": "褒国公主（孟知祥妹）", "aliases": ["褒国公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》记为孟知祥的妹妹、伊审征的母亲。《宋史》另记伊审征之父娶孟知祥之女崇华公主，未将两位公主合并，亲属叙述仍待进一步校核。生卒年未载。", "biography": null, "status": "draft", "id": "3ca38bcd-76bf-5ced-b9cc-455d40467262"}, {"name": "王昭远", "aliases": ["王昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "成都人，后蜀官员。年少时跟随僧人智諲进入孟知祥府中，后来被留下侍奉孟昶；《新五代史》《宋史》记当时十三岁。948年由茶酒库使任通奏使、知枢密院事，获委机务和府库财物支配。没有据十三岁反推出生年。", "biography": null, "status": "draft", "id": "49c83873-4e4d-515e-9f4b-ebbf460d53fd"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "郑珙", "aliases": ["鄭珙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "青州人，刘崇的节度判官。刘崇因与郭威有嫌隙而忧惧时，郑珙劝他谋求自保；《新五代史》也记类似谋议，但安排在郭威讨平三镇之后，与《资治通鉴》的叙述顺序不同。生卒年未据本次原文确定。", "biography": null, "status": "draft", "id": "d8579c34-3e02-5140-b6af-9f52a59f202e"}, {"name": "姚汉英", "aliases": ["姚漢英"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周左金吾将军，《旧五代史》称左金吾卫将军。951年五月奉命与华光裔出使契丹，《资治通鉴》记使团被契丹扣留。生卒年未载。", "biography": null, "status": "draft", "id": "f01a3c46-0229-5e9c-b145-f5e31cb93c25"}, {"name": "华光裔", "aliases": ["華光裔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周前右神武将军。《旧五代史》记他于951年五月己巳与姚汉英一同奉命出使契丹。生卒年未载。", "biography": null, "status": "draft", "id": "e43297e3-3d01-57b0-84fe-25109fa64f00"}, {"name": "孙方简", "aliases": ["孫方簡", "孙方谏", "孫方諫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》称中山人，聚众于狼山，归附后晋后任东北招收指挥使，后来转投契丹并拘执刘延翰。《宋史》孙行友传写作孙方谏，记他是孙行友的兄子；《资治通鉴》记孙行友是其弟，亲属记载冲突待核。姓名字形与主体按狼山、职衔和事迹对应复用，生卒年未核。", "biography": null, "status": "draft", "id": "17e0109c-1d9d-5437-a7d0-5c7be7b6beb8"}, {"name": "李彝殷", "aliases": ["李彜殷", "李彝兴", "李彝興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彝殷，行军司马、权知军州事者。", "biography": null, "status": "draft", "id": "22edc111-ae26-5bce-a26b-3ae072425377"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
